      SUBROUTINE GATHERCC     FORM NORMALIZED EQUATIONS FOR FITTING FROM PARTIAL DERIVATIVESCC     LIST OF COMMON BLOCKSC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'DATA0A.CIN'      INCLUDE 'ELM0A.CIN'      INCLUDE 'ELM10A.CIN'      INCLUDE 'ELM10B.CIN'      INCLUDE 'ELM10D.CIN'      INCLUDE 'ELM22A.CIN'      INCLUDE 'ELM23.CIN'CC------------------------------------------------------------CC     STORE CONSTRAINT IN COVARIANCE MATRIXC      NP1 = NV1 + 1      IF (TYPE .EQ. 38) GO TO 200      IF (TYPE .EQ. 22) GO TO 100      IF (NV3 .LT. 1) GO TO 200      DO 10 L1 = 1, NP1      DO 10 L2 = 1, L1      CA(L1,L2) = CA(L1,L2) + CW * A(L1) * A(L2)   10 CONTINUE      GO TO 200CC     STORE MATRIX ELEMENT IN REGISTERC  100 J = JREG      IF (JTIE .EQ. 100) GO TO 150      LREG(J) = .TRUE.      REG(J) = COC      IF (NV3 .LT. 1) GO TO 200      DO 110 N = 1, NPVAR  110 DREG(J,N) = 0.0      IF (NV1 .LT. 1) GO TO 200      DO 120 N = 1, NV1  120 DREG(J,N) = A(N+1)      GO TO 200CC     STORE MATRIX ELEMENT AND DERIVATIVES IN PSEUDO-PARAMETERC  150 DATA(J) = COC      IF (NV3 .LT. 1) GO TO 200      DO 160 N = 1, NPVAR  160 DATA(J+N) = 0.0      IF (NV1 .LT. 1) GO TO 200      DO 170 N = 1, NV1  170 DATA(J+N) = A(N+1)C  200 RETURN      END